public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int[] toys = new int[N];
        for (int i = 0; i < N; i++) {
            toys[i] = Integer.parseInt(br.readLine());
        }

        // prefixCount[type][pos] = count of 'type' in toys[0..pos-1]
        int[][] prefixCount = new int[M + 1][N + 1];
        for (int i = 0; i < N; i++) {
            for (int t = 1; t <= M; t++) {
                prefixCount[t][i + 1] = prefixCount[t][i];
            }
            prefixCount[toys[i]][i + 1]++;
        }

        // totalCount[type]
        int[] totalCount = new int[M + 1];
        for (int i = 0; i < N; i++) {
            totalCount[toys[i]]++;
        }

        int fullMask = (1 << M) - 1;
        int[][] dp = new int[1 << M][M + 1];
        for (int[] row : dp) Arrays.fill(row, -1);
        dp[0][0] = 0;

        for (int mask = 0; mask < (1 << M); mask++) {
            int placed = 0;
            for (int t = 1; t <= M; t++) {
                if ((mask & (1 << (t - 1))) != 0) placed += totalCount[t];
            }

            for (int last = 0; last <= M; last++) {
                if (dp[mask][last] == -1) continue;
                for (int next = 1; next <= M; next++) {
                    if ((mask & (1 << (next - 1))) != 0) continue;
                    int newMask = mask | (1 << (next - 1));
                    // toys of type 'next' that we can keep: those in the segment [placed, placed+totalCount[next])
                    int keep = prefixCount[next][placed + totalCount[next]] - prefixCount[next][placed];
                    dp[newMask][next] = Math.max(dp[newMask][next], dp[mask][last] + keep);
                }
            }
        }

        int maxKeep = 0;
        for (int last = 1; last <= M; last++) {
            maxKeep = Math.max(maxKeep, dp[fullMask][last]);
        }
        System.out.println(N - maxKeep);
    }
}

