        Arrays.fill(last, -1);
        int M = 0;
        for(int i=0;i<N;i++){
            a[i]=Integer.parseInt(br.readLine().trim());
            M=Math.max(M,a[i]);
            if(first[a[i]]==Integer.MAX_VALUE) first[a[i]]=i+1;
            last[a[i]]=i+1;
        }
        int[] dp = new int[1<<M];
        Arrays.fill(dp, Integer.MAX_VALUE/2);
        dp[0]=0;
        for(int S=0;S<(1<<M);S++){
            if(dp[S]==Integer.MAX_VALUE/2) continue;
            for(int t=0;t<M;t++){
                if((S&(1<<t))!=0) continue;
                if(first[t+1]>dp[S]){
                    int ns=S|(1<<t);
                    dp[ns]=Math.min(dp[ns],last[t+1]);
                }
            }
        }
        int full=(1<<M)-1;
        System.out.println(dp[full]<Integer.MAX_VALUE/2 ? N-N : "impossible");
        // Actually answer is N - (toys kept). If dp[full] is valid, we kept all N.
        // But we might not keep all - need rethink... 
        // If dp[full] is valid means we can keep ALL toys with 0 removals.
        // Otherwise we need to remove some. The answer = N - max kept.
        // Max kept when keeping all of chosen types: sum of counts of types in S where dp[S] is valid (full set reached)
        // Hmm, the answer is 0 if dp[full] < inf, else we need partial.
        int[] cnt = new int[M+1];
        for(int x:a) cnt[x]++;
        int maxKeep=0;
        for(int S=0;S<(1<<M);S++){
            if(dp[S]<Integer.MAX_VALUE/2){
                int keep=0;
                for(int t=0;t<M;t++) if((S&(1<<t))!=0) keep+=cnt[t+1];
                maxKeep=Math.max(maxKeep,keep);
            }
        }
        System.out.println(N-maxKeep);
    }
}

