public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int M = fs.nextInt();

        int[] a = new int[N];
        int[] cnt = new int[M];
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextInt() - 1;
            cnt[a[i]]++;
        }

        // prefix[t][i] = number of toys of type t in positions [0, i)
        int[][] prefix = new int[M][N + 1];
        for (int t = 0; t < M; t++) {
            for (int i = 0; i < N; i++) {
                prefix[t][i + 1] = prefix[t][i] + (a[i] == t ? 1 : 0);
            }
        }

        int size = 1 << M;

        // sumLen[mask] = total length occupied by types in mask
        int[] sumLen = new int[size];
        for (int mask = 1; mask < size; mask++) {
            int b = Integer.numberOfTrailingZeros(mask);
            int prev = mask ^ (1 << b);
            sumLen[mask] = sumLen[prev] + cnt[b];
        }

        // dp[mask] = maximum number of toys that can stay in place
        // when arranging exactly the set of types in mask first.
        int[] dp = new int[size];
        Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < size; mask++) {
            if (dp[mask] < 0) continue;
            int start = sumLen[mask];
            for (int t = 0; t < M; t++) {
                if ((mask & (1 << t)) != 0) continue;
                int end = start + cnt[t];
                int keep = prefix[t][end] - prefix[t][start];
                int nextMask = mask | (1 << t);
                dp[nextMask] = Math.max(dp[nextMask], dp[mask] + keep);
            }
        }

        int maxKeep = dp[size - 1];
        int answer = N - maxKeep;
        System.out.println(answer);
    }
}

