    vector<int> len(S, 0);
    for (int mask = 1; mask < S; mask++) {
        int b = __builtin_ctz(mask);
        len[mask] = len[mask ^ (1 << b)] + cnt[b];
    }

    const int INF = 1e9;
    vector<int> dp(S, INF);
    dp[0] = 0;

    // dp[mask] = maximum number of toys already in correct places
    // among the first len[mask] positions, arranging exactly the types in mask.
    // We store minimum moved = len[mask] - kept, equivalently:
    // transition adds misplaced count in the block of the new type.
    for (int mask = 0; mask < S; mask++) {
        int start = len[mask];
        for (int t = 0; t < M; t++) {
            if (mask & (1 << t)) continue;
            int nmask = mask | (1 << t);
            int l = start;
            int r = start + cnt[t];
            int correct = prefix[t][r] - prefix[t][l];
            int moved_in_block = cnt[t] - correct;
            dp[nmask] = min(dp[nmask], dp[mask] + moved_in_block);
        }
    }

    cout << dp[S - 1] << '\n';
    return 0;
}

