#define MAX_N 200000
#define MAX_M 200000

int a[MAX_N];               // original array
int cnt[MAX_M + 1];         // total count of each type
int appear[MAX_M + 1];      // flag if type appears at least once
int freq[MAX_M + 1];        // frequency in current window

// min function
int min(int x, int y) {
    return x < y ? x : y;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    int distinct = 0;
    for (int i = 0; i < N; i++) {
        scanf("%d", &a[i]);
        if (cnt[a[i]] == 0) distinct++;
        cnt[a[i]]++;
        appear[a[i]] = 1;
    }

    // If only one distinct type, no removal needed
    if (distinct == 1) {
        printf("0\n");
        return 0;
    }

    int ans = N; // worst case: remove all

    // Try each possible type as the "fixed" type that stays in place
    // For each type x, we consider the segment where all x's are kept,
    // and we want to keep as many non-x toys inside that segment as possible
    // such that they form no more than one contiguous block of each other type.
    // Equivalent to: find a contiguous segment that contains all x's,
    // and the number of distinct types other than x inside the segment is at most 1.
    // The toys we keep = cnt[x] + max occurrences of a single other type inside that segment.

    for (int x = 1; x <= M; x++) {
        if (!appear[x]) continue;

        // Two-pointer to find minimal segment covering all x's
        int need = cnt[x];
        int have = 0;
        int l = 0;

        // First, find initial window that contains all x's
        for (int r = 0; r < N && have < need; r++) {
            if (a[r] == x) have++;
        }
        // Now have == need, find the left boundary
        // Actually we need to find the minimal window covering all x's
        // Reset
        have = 0;
        l = 0;
        int minL = 0, minR = N-1;
        int found = 0;

        // Sliding window to find minimal window containing all x's
        for (int r = 0; r < N; r++) {
            if (a[r] == x) have++;
            while (have == need) {
                if (!found || (r - l < minR - minL)) {
                    minL = l;
                    minR = r;
                    found = 1;
                }
                if (a[l] == x) have--;
                l++;
            }
        }

        // Now the minimal window is [minL, minR]
        // We consider windows that extend from minL to some R >= minR,
        // or from some L <= minL to minR, or both.
        // Actually we need to consider all windows that contain all x's.
        // The optimal window will have its left bound between 0 and minL,
        // and right bound between minR and N-1.
        // For each possible left bound L (0..minL), we find the best right bound.

        // Precompute frequency of non-x types for quick evaluation
        // We'll use two-pointer expanding from the minimal window

        // Reset frequencies
        memset(freq, 0, sizeof(freq));
        int curL = minL, curR = minR;
        int maxOther = 0;
        int secondMax = 0; // not needed actually, we just need maxOther

        // Count frequencies in minimal window
        for (int i = curL; i <= curR; i++) {
            if (a[i] != x) {
                freq[a[i]]++;
                if (freq[a[i]] > maxOther) maxOther = freq[a[i]];
            }
        }

        // Keep candidates: ans = min(ans, N - (cnt[x] + maxOther))
        int keep = cnt[x] + maxOther;
        ans = min(ans, N - keep);

        // Expand to the right
        int tempL = curL, tempR = curR;
        int tempFreq[MAX_M + 1];
        memcpy(tempFreq, freq, sizeof(freq));
        int tempMax = maxOther;

        for (int R = curR + 1; R < N; R++) {
            if (a[R] != x) {
                tempFreq[a[R]]++;
                if (tempFreq[a[R]] > tempMax) tempMax = tempFreq[a[R]];
            }
            keep = cnt[x] + tempMax;
            ans = min(ans, N - keep);
        }

        // Expand to the left from minimal window
        // Reset
        memcpy(tempFreq, freq, sizeof(freq));
        tempMax = maxOther;

        for (int L = curL - 1; L >= 0; L--) {
            if (a[L] != x) {
                tempFreq[a[L]]++;
                if (tempFreq[a[L]] > tempMax) tempMax = tempFreq[a[L]];
            }
            // Now for this left bound, we need to consider all right bounds >= curR
            // We can just evaluate with curR first, then expand right again
            keep = cnt[x] + tempMax;
            ans = min(ans, N - keep);

            // Expand right from curR for this left bound
            int tempFreq2[MAX_M + 1];
            memcpy(tempFreq2, tempFreq, sizeof(tempFreq));
            int tempMax2 = tempMax;

            for (int R = curR + 1; R < N; R++) {
                if (a[R] != x) {
                    tempFreq2[a[R]]++;
                    if (tempFreq2[a[R]] > tempMax2) tempMax2 = tempFreq2[a[R]];
                }
                keep = cnt[x] + tempMax2;
                ans = min(ans, N - keep);
            }
        }
    }

    printf("%d\n", ans);
    return 0;
}

