    for (int i = 0; i < M; i++) start[i + 1] = start[i] + cnt[i];

    int *pref = (int *)calloc((M + 1) * (N + 1), sizeof(int));
    for (int t = 0; t < M; t++) {
        int base = t * (N + 1);
        int next = (t + 1) * (N + 1);
        pref[next] = 0;
        for (int i = 0; i < N; i++) {
            pref[next + i + 1] = pref[next + i] + (a[i] == t);
        }
    }

    int S = 1 << M;
    int *dp = (int *)malloc(sizeof(int) * S);
    for (int i = 0; i < S; i++) dp[i] = -1;
    dp[0] = 0;

    for (int mask = 0; mask < S; mask++) {
        if (dp[mask] < 0) continue;

        int len = 0;
        for (int t = 0; t < M; t++) {
            if (mask & (1 << t)) len += cnt[t];
        }

        for (int t = 0; t < M; t++) {
            if (mask & (1 << t)) continue;
            int l = len;
            int r = len + cnt[t];
