int main() {
    int N, M;
    scanf("%d %d", &N, &M);
    int *a = malloc(N * sizeof(int));
    int *cnt = calloc(M+1, sizeof(int));
    for (int i = 0; i < N; i++) { scanf("%d", &a[i]); a[i]--; cnt[a[i]]++; }
    int **pos = malloc(M * sizeof(int*));
    int *idx = calloc(M, sizeof(int));
    for (int i = 0; i < M; i++) pos[i] = malloc(cnt[i] * sizeof(int));
    for (int i = 0; i < N; i++) pos[a[i]][idx[a[i]]++] = i;
    // dp[t] = max toys kept where t is last completed type, value = (kept_count, last_position)
    // We store: best[t] = max toys kept ending with type t, and the last position used
    int *best = calloc(M, sizeof(int));
    int *last_pos = malloc(M * sizeof(int));
    for (int i = 0; i < M; i++) last_pos[i] = pos[i][cnt[i]-1];
    // Initialize: just type t alone
    for (int t = 0; t < M; t++) best[t] = cnt[t];
    // For each type t, try appending it after each other type p
    // Need to iterate in topological order... use repeated relaxation or sort by last_pos
    // Actually this needs proper ordering. Let's do O(M^2) DP.
    // Sort types by their last position? No, we need to consider all orderings.
    // dp: for each type t as the current last type, best[t] = max toys kept
    // Transition: best[t] = max(cnt[t], max over p where last_pos[p] < first_pos_of_t_after_last_p)
    // This is complex. Let me store (best_kept, last_position_used) per type.
    int *lp = malloc(M * sizeof(int)); // last position of kept toys for this type
    for (int t = 0; t < M; t++) { best[t] = cnt[t]; lp[t] = pos[t][cnt[t]-1]; }
    // Relax M times
    for (int iter = 0; iter < M; iter++) {
        int updated = 0;
        for (int t = 0; t < M; t++) {
            for (int p = 0; p < M; p++) {
                if (p == t) continue;
                int split = lp[p]; // last pos of p
                // count toys of type t after split
                int lo = 0, hi = cnt[t];
                while (lo < hi) { int mid=(lo+hi)/2; if(pos[t][mid]<=split) lo=mid+1; else hi=mid; }
                int take = cnt[t] - lo;
                if (take > 0 && best[p] + take > best[t]) {
                    best[t] = best[p] + take;
                    lp[t] = pos[t][cnt[t]-1];
                    updated = 1;
                }
            }
        }
        if (!updated) break;
    }
    int maxkeep = 0;
    for (int t = 0; t < M; t++) if (best[t] > maxkeep) maxkeep = best[t];
    printf("%d\n", N - maxkeep);
    return 0;
}
